def is_indian_trusted_domain(url):
    """Check if URL is from a trusted Indian or global institutional domain"""
    from urllib.parse import urlparse
    try:
        parsed = urlparse(url)
        hostname = parsed.hostname if parsed.hostname else ''
        hostname_lower = hostname.lower()
        
        # Check global institutional domains first (high trust)
        for domain in GLOBAL_INSTITUTIONAL_DOMAINS:
            if hostname_lower == domain or hostname_lower.endswith('.' + domain):
                return True
        
        # Check Indian trusted domains
        for domain in INDIAN_TRUSTED_DOMAINS:
            if hostname_lower == domain or hostname_lower.endswith('.' + domain):
                return True
        
        return False
    except:
        return False

if __name__ == '__main__':
    # Test
    test_urls = [
        "https://www.flipkart.com/",
        "https://www.amazon.in/",
        "https://paytm.com/",
        "https://www.zomato.com/",
    ]
    
    print("Testing Indian Domain Recognition:")
    print("=" * 60)
    for url in test_urls:
        is_trusted = is_indian_trusted_domain(url)
        print(f"{url:<40} {'✓ TRUSTED' if is_trusted else '✗ NOT TRUSTED'}")
